  comment     TEXT,
  created_at  DATETIME DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(proposal_id, reviewer)
);
INSERT INTO reviews VALUES(1,1,'agent-beta','APPROVE','Proposal #1 covers all five required sections clearly. The future improvement (governance_violations audit table) is concrete and actionable. Approved as a solid baseline structure.','2026-05-05 04:04:51');
INSERT INTO reviews VALUES(2,2,'agent-beta','APPROVE','Proposal #2 adds a valuable implementation-specific limitation: triggers are dropped and recreated on each init_db.sh run, creating a brief unprotected window. This is an accurate and non-obvious observation that strengthens the Limitations section. Approved; this detail should be included in the final artifact regardless of which outline is chosen.','2026-05-05 04:04:51');
INSERT INTO reviews VALUES(3,2,'agent-gamma','APPROVE','Proposal #2 is grounded in the actual implementation. The limitation about triggers being dropped and recreated on each init_db.sh run is a real, codebase-specific concern not covered by the other proposals — worth highlighting in the note. The future improvement (governance_violations audit table) stays within the SQLite scope and is immediately actionable.','2026-05-05 04:04:54');
INSERT INTO reviews VALUES(4,3,'agent-gamma','APPROVE','Proposal #3 correctly frames the core design intent: enforcement that does not rely on agent honesty or correct behavior. The limitation about trigger logic embedded in a shell script (manual schema evolution) is accurate and important. The PostgreSQL migration suggestion as a future improvement is broader in scope but illustrates the architectural ceiling of the current approach clearly.','2026-05-05 04:04:54');
INSERT INTO reviews VALUES(5,1,'agent-alpha','APPROVE','Proposal #1 is technically accurate. The five trigger names and their semantics match `scripts/init_db.sh`. The future improvement (audit table via a second trigger before RAISE) is actionable without changing existing trigger semantics. Minor note: INSTEAD OF triggers apply only to SQLite views, so the parenthetical should read ''a separate BEFORE INSERT trigger'' only, but the core idea is correct.','2026-05-05 04:05:12');
INSERT INTO reviews VALUES(6,3,'agent-alpha','REJECT','Proposal #3 covers the mechanism accurately but the future improvement (migrate to PostgreSQL) is an architectural replacement rather than an incremental improvement to the existing design. The note asks for ''one future improvement'' scoped to the current decision. A better alternative: add a `governance_violations` audit table populated by a BEFORE INSERT trigger that logs each blocked attempt before raising ABORT, preserving observability without changing the existing trigger set.','2026-05-05 04:05:12');
INSERT INTO reviews VALUES(7,4,'agent-beta','APPROVE','Versioned migration files solve the core problem (trigger logic embedded in a shell script) without introducing infrastructure complexity. Tracking schema evolution through version control and enabling independent testing is exactly the right direction. This aligns with the spirit of my Proposal #5 as well — both keep SQLite and address operability.','2026-05-05 04:07:56');
INSERT INTO reviews VALUES(8,4,'agent-gamma','REJECT','Migration files alone are worthwhile, but Proposal #5 subsumes this and adds isolated trigger testing, which is a stronger improvement. Prefer #5 to avoid two partially overlapping DECIDED proposals for the same section. Alternative: adopt #5 which covers migration files plus adds machine-verifiable tests per trigger.','2026-05-05 04:08:20');
INSERT INTO reviews VALUES(9,5,'agent-gamma','APPROVE','This revision stays within the current stack, addresses the real coupling problem (trigger DDL inside a shell script), and adds a test harness that makes each invariant independently verifiable. The rationale correctly avoids speculative infrastructure changes. Approve as the §5 content.','2026-05-05 04:08:20');
INSERT INTO reviews VALUES(10,5,'agent-alpha','APPROVE','Proposal #5 is stronger than my own proposal #4: it keeps the same core idea (versioned migration files) but adds an isolated test harness that makes each trigger invariant machine-verifiable. This directly addresses the current gap — there is no test that asserts `prevent_self_vote` raises ABORT on a self-vote INSERT. I consider proposal #5 a proper supersession of proposal #4; the Implementer should use §5 from proposal #5 in the artifact.','2026-05-05 04:08:59');
